CREATE TABLE colab_sessions (owner_id TEXT PRIMARY KEY,id TEXT NOT NULL UNIQUE,pair_hash TEXT UNIQUE,pair_expires_at TEXT NOT NULL,session_hash TEXT UNIQUE,state TEXT NOT NULL CHECK(state IN ('pending','paired','revoked')),mode TEXT NOT NULL CHECK(mode IN ('manual','active')),expires_at TEXT NOT NULL,last_seen_at TEXT,poll_window INTEGER NOT NULL DEFAULT 0,poll_count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,FOREIGN KEY(owner_id) REFERENCES owners(id) ON DELETE CASCADE);
CREATE TABLE colab_usage (owner_id TEXT NOT NULL,lane TEXT NOT NULL,window_hour INTEGER NOT NULL,count INTEGER NOT NULL,PRIMARY KEY(owner_id,lane),FOREIGN KEY(owner_id) REFERENCES owners(id) ON DELETE CASCADE);
CREATE TABLE colab_jobs (owner_id TEXT NOT NULL,id TEXT NOT NULL,session_id TEXT NOT NULL,conversation_id TEXT NOT NULL,revision INTEGER NOT NULL,turn_token TEXT NOT NULL,context_key TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('queued','running','completed','failed','expired','cancelled')),payload_json TEXT,user_text TEXT,reply TEXT,lease_hash TEXT,lease_until TEXT,expires_at TEXT NOT NULL,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,PRIMARY KEY(owner_id,id),FOREIGN KEY(owner_id,conversation_id) REFERENCES conversations(owner_id,id) ON DELETE CASCADE);
CREATE UNIQUE INDEX colab_one_active ON colab_jobs(owner_id,session_id) WHERE status IN ('queued','running');
CREATE INDEX colab_jobs_expiry ON colab_jobs(owner_id,expires_at,status);
